CREATE TABLE app.rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL REFERENCES app.institutes(id),code text NOT NULL,name text NOT NULL,capacity integer CHECK(capacity>0),version integer NOT NULL DEFAULT 1,UNIQUE(institute_id,id),UNIQUE(institute_id,code));
CREATE TABLE app.timetable_imports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL,term_id uuid NOT NULL,asset_id uuid NOT NULL,uploaded_by uuid NOT NULL REFERENCES auth.users(id),base_revision integer NOT NULL,preview_json jsonb NOT NULL DEFAULT '{}',preview_hash text,source_hash text,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','validating','ready','rejected','committed')),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(institute_id,id),UNIQUE(asset_id),FOREIGN KEY(institute_id,term_id) REFERENCES app.terms(institute_id,id),FOREIGN KEY(institute_id,asset_id) REFERENCES app.media_assets(institute_id,id));
CREATE TABLE app.schedule_series(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL,term_id uuid NOT NULL,offering_id uuid NOT NULL,teacher_id uuid NOT NULL,room_id uuid NOT NULL,entry_key text NOT NULL,weekday integer NOT NULL CHECK(weekday BETWEEN 0 AND 6),local_start time NOT NULL,local_end time NOT NULL,effective_from date NOT NULL,effective_until date NOT NULL,timezone text NOT NULL CHECK(timezone='Asia/Kolkata'),revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),CHECK(local_end>local_start),CHECK(effective_until>=effective_from),UNIQUE(institute_id,id),UNIQUE(institute_id,term_id,entry_key),FOREIGN KEY(institute_id,term_id) REFERENCES app.terms(institute_id,id),FOREIGN KEY(institute_id,offering_id) REFERENCES app.offerings(institute_id,id),FOREIGN KEY(institute_id,teacher_id) REFERENCES app.teachers(institute_id,id),FOREIGN KEY(institute_id,room_id) REFERENCES app.rooms(institute_id,id));
CREATE TABLE app.schedule_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL,series_id uuid NOT NULL,occurrence_date date NOT NULL,action text NOT NULL CHECK(action IN ('cancel','replace')),replacement_start timestamptz,replacement_end timestamptz,replacement_teacher_id uuid,replacement_room_id uuid,reason text NOT NULL,UNIQUE(institute_id,series_id,occurrence_date),FOREIGN KEY(institute_id,series_id) REFERENCES app.schedule_series(institute_id,id),FOREIGN KEY(institute_id,replacement_teacher_id) REFERENCES app.teachers(institute_id,id),FOREIGN KEY(institute_id,replacement_room_id) REFERENCES app.rooms(institute_id,id));
CREATE TABLE app.calendar_exceptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL,term_id uuid NOT NULL,local_date date NOT NULL,action text NOT NULL CHECK(action IN ('holiday','teaching_day')),reason text NOT NULL,UNIQUE(institute_id,term_id,local_date),FOREIGN KEY(institute_id,term_id) REFERENCES app.terms(institute_id,id));
ALTER TABLE app.sessions ADD COLUMN series_id uuid;
ALTER TABLE app.sessions ADD COLUMN room_id uuid;
ALTER TABLE app.sessions ADD CONSTRAINT session_series_fk FOREIGN KEY(institute_id,series_id) REFERENCES app.schedule_series(institute_id,id);
ALTER TABLE app.sessions ADD CONSTRAINT session_room_fk FOREIGN KEY(institute_id,room_id) REFERENCES app.rooms(institute_id,id);
CREATE TABLE app.reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL,session_id uuid NOT NULL,publication_id uuid,kind text NOT NULL CHECK(kind IN ('draft','final')),source_version integer NOT NULL,snapshot_json jsonb NOT NULL,snapshot_hash text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','ready','failed')),csv_asset_id uuid,pdf_asset_id uuid,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',UNIQUE(institute_id,id),UNIQUE(institute_id,session_id,kind,source_version),FOREIGN KEY(institute_id,session_id) REFERENCES app.sessions(institute_id,id),FOREIGN KEY(institute_id,publication_id) REFERENCES app.publications(institute_id,id),FOREIGN KEY(institute_id,csv_asset_id) REFERENCES app.media_assets(institute_id,id),FOREIGN KEY(institute_id,pdf_asset_id) REFERENCES app.media_assets(institute_id,id));
CREATE TABLE app.deliveries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institute_id uuid NOT NULL,report_id uuid NOT NULL,recipient_user_id uuid NOT NULL REFERENCES auth.users(id),recipient_email text NOT NULL,dedup_key text NOT NULL,status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sending','sent','failed')),provider_message_id text,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,error_code text,UNIQUE(institute_id,id),UNIQUE(institute_id,dedup_key),FOREIGN KEY(institute_id,report_id) REFERENCES app.reports(institute_id,id));
ALTER TABLE app.media_assets DROP CONSTRAINT media_assets_purpose_check;
ALTER TABLE app.media_assets ADD CONSTRAINT media_assets_purpose_check CHECK(purpose IN ('enrollment','classroom','timetable','report'));
ALTER TABLE app.media_assets DROP CONSTRAINT media_assets_mime_type_check;
ALTER TABLE app.media_assets ADD CONSTRAINT media_assets_mime_type_check CHECK(mime_type IN ('video/mp4','video/webm','text/csv','application/pdf'));
ALTER TABLE app.jobs DROP CONSTRAINT jobs_resource_kind;
ALTER TABLE app.jobs ADD COLUMN timetable_import_id uuid;
ALTER TABLE app.jobs ADD COLUMN report_id uuid;
ALTER TABLE app.jobs ADD COLUMN delivery_id uuid;
ALTER TABLE app.jobs ADD CONSTRAINT jobs_timetable_fk FOREIGN KEY(institute_id,timetable_import_id) REFERENCES app.timetable_imports(institute_id,id);
ALTER TABLE app.jobs ADD CONSTRAINT jobs_report_fk FOREIGN KEY(institute_id,report_id) REFERENCES app.reports(institute_id,id);
ALTER TABLE app.jobs ADD CONSTRAINT jobs_delivery_fk FOREIGN KEY(institute_id,delivery_id) REFERENCES app.deliveries(institute_id,id);
ALTER TABLE app.jobs ADD CONSTRAINT jobs_resource_kind CHECK(
 num_nonnulls(enrollment_attempt_id,capture_id,timetable_import_id,report_id,delivery_id)=1 AND
 ((kind='enrollment' AND enrollment_attempt_id IS NOT NULL) OR(kind='recognition' AND capture_id IS NOT NULL) OR(kind='timetable' AND timetable_import_id IS NOT NULL) OR(kind='report' AND report_id IS NOT NULL) OR(kind='delivery' AND delivery_id IS NOT NULL)));
DO $$ DECLARE t text; r text; BEGIN
 FOREACH t IN ARRAY ARRAY['rooms','timetable_imports','schedule_series','schedule_exceptions','calendar_exceptions','reports','deliveries'] LOOP
 EXECUTE format('ALTER TABLE app.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE app.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON app.%I FROM PUBLIC',t);EXECUTE format('GRANT SELECT,INSERT,UPDATE ON app.%I TO facetrack_api',t);
 EXECUTE format('CREATE POLICY tenant_access ON app.%I USING(institute_id=app.tenant_id() AND (app.is_member() OR app.is_worker())) WITH CHECK(institute_id=app.tenant_id() AND (app.is_member() OR app.is_worker()))',t);
 END LOOP;
 FOR r IN SELECT rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role') LOOP EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA app FROM %I',r);END LOOP;
END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['terms','courses','class_groups','offerings','offering_teachers','teachers'] LOOP EXECUTE format('CREATE POLICY worker_academic_read ON app.%I FOR SELECT USING(institute_id=app.tenant_id() AND app.is_worker())',t);END LOOP;END $$;
CREATE FUNCTION app.faculty_can_teach(a uuid,o uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app AS $$
 SELECT (app.is_member() OR app.is_worker()) AND EXISTS(SELECT 1 FROM app.offering_teachers ot JOIN app.teachers t ON t.institute_id=ot.institute_id AND t.id=ot.teacher_id JOIN app.memberships m ON m.institute_id=t.institute_id AND m.auth_user_id=t.auth_user_id JOIN app.institutes i ON i.id=t.institute_id WHERE ot.institute_id=app.tenant_id() AND ot.offering_id=o AND t.auth_user_id=a AND ot.status='active' AND t.status='approved' AND m.role='teacher' AND m.status='active' AND i.status='active') $$;
REVOKE ALL ON FUNCTION app.faculty_can_teach(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.faculty_can_teach(uuid,uuid) TO facetrack_api;
GRANT UPDATE(schedule_revision,version) ON app.terms TO facetrack_api;
DO $$ DECLARE r text; BEGIN FOR r IN SELECT rolname FROM pg_roles WHERE rolname IN ('anon','authenticated','service_role') LOOP EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA app FROM %I',r);END LOOP;END $$;
